import{i as e}from"./client-DFVfVTop.js";async function t(){let t=await e.get(`/strategy/api/books`);if(t.data.status!==`success`||!t.data.books)throw Error(t.data.message||`Failed to load strategy books`);return t.data.books}async function n(t,n={}){let r=await e.get(`/strategy/api/books/${t}/timeline`,{params:n});if(r.data.status!==`success`)throw Error(r.data.message||`Failed to load timeline`);return r.data}export{t as n,n as t};